    if not isinstance(scenario, str):
        raise TypeError("scenario must be a string")
    if not isinstance(liar_count, set):
        raise TypeError("liar_count must be a set")
    if not isinstance(statements, dict):
        raise TypeError("statements must be a dict")
    if not isinstance(days_of_week, set):
        raise TypeError("days_of_week must be a set")

    # Validate contents of sets and dict
    for name in liar_count:
        if not isinstance(name, str):
            raise ValueError("liar_count must contain strings only")
    for day in days_of_week:
        if not isinstance(day, str):
            raise ValueError("days_of_week must contain strings only")
    for participant, stmts in statements.items():
        if not isinstance(participant, str):
            raise ValueError("statements keys must be strings")
        if not isinstance(stmts, list):
            raise ValueError(f"statements for participant {participant} must be a list")
        for s in stmts:
            if not isinstance(s, str):
                raise ValueError(f"statement '{s}' for participant {participant} must be a string")

    # Helper to determine truth of a statement
    def evaluate_statement(participant: str, stmt: str) -> bool:
        # Skip statements about days of the week
        for day in days_of_week:
            if day in stmt:
                return None  # indicates to skip

        # Clean punctuation
        cleaned = stmt.strip().rstrip('.').strip()
        tokens = cleaned.split()
        if not tokens:
            return None

        # Determine subject
        if tokens[0] == "I":
            subject = participant
        else:
            subject = tokens[0]

        # Determine if statement is about guilt
        if len(tokens) >= 3 and tokens[1] in ("am", "is"):
            if tokens[2] == "guilty":
                guilty = True
            elif len(tokens) >= 4 and tokens[2] == "not" and tokens[3] == "guilty":
                guilty = False
            else:
                return None  # unrecognized pattern
        else:
            return None  # unrecognized pattern

        # Evaluate truth
        if guilty:
            return subject == scenario
        else:
            return subject != scenario

    # Iterate over all statements
    for participant, stmts in statements.items():
        for stmt in stmts:
            truth = evaluate_statement(participant, stmt)
            if truth is None:
                continue  # skip this statement
            is_liar = participant in liar_count
            if is_liar and truth:
                return False  # liar told truth
            if not is_liar and not truth:
                return False  # truth-teller lied

    return True

